import {
    Component,
    ElementRef,
    HostListener,
    OnDestroy,
    OnInit,
    ViewChild,
} from '@angular/core';
import { SupplyService } from '../supply.service';
import { Subscription } from 'rxjs';
import { tap } from 'rxjs/operators';
import { AutoCompleteCompleteEvent } from 'primeng/autocomplete';
import { Products } from 'src/app/core/interfaces/stock.interface';
import { StockService } from 'src/app/stock/stock.service';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { PurchaseForm } from 'src/app/core/interfaces/supply.interface';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { ConfirmationService } from 'primeng/api';
import { LocalStorageService } from 'src/app/_services/local-storage.service';
import { Table } from 'primeng/table';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';

@Component({
    selector: 'supply-form',
    templateUrl: './supply-form.component.html',
    styleUrls: ['./supply-form.component.scss'],
})
export class SupplyFormComponent implements OnInit, OnDestroy {
    // @ViewChild('dt') dt: ElementRef;
    @ViewChild('barcodeInput', { read: ElementRef }) barcodeInput: ElementRef;
    @ViewChild('invoiceTable') invoiceTable: Table;

    constructor(
        private supplyService: SupplyService,
        private stockService: StockService,
        private notificationService: NotificationsService,
        private confirmationService: ConfirmationService,
        private localStorageService: LocalStorageService,
        private auxiliaryService: AuxiliaryService
    ) {}

    // get view height for scrollable invoice table
    vh = this.localStorageService.getSupplyPageViewHeight();

    subscriptions = new Subscription();
    invoice;
    invoiceTotal;
    barcode;
    barcodeResponse;
    supplierInvalid: boolean = false;

    submitted: boolean = false;

    suppliers?: AuxiliaryAccount[];

    items: Products[];
    searchedItems: any;

    // products dialog visible
    dialogVisible: boolean = false;

    // bill form
    purchaseForm: PurchaseForm;

    // exchange rate
    exchangeRate;

    // on init hook
    ngOnInit(): void {
        this.subscriptions.add(
            this.stockService.items.subscribe((res) => {
                this.items = res;
            })
        );
        this.subscriptions.add(
            this.stockService.exchangeRate.subscribe((res) => {
                this.exchangeRate = res;
            })
        );
        this.subscriptions.add(
            this.supplyService.purchaseForm.subscribe((res: PurchaseForm) => {
                this.purchaseForm = res;
            })
        );
        this.subscriptions.add(
            this.supplyService.invoice
                .pipe(
                    tap((re) => {
                        this.supplyService.calculateTotal();
                    })
                )
                .subscribe((res) => {
                    this.invoice = res;
                })
        );
        this.subscriptions.add(
            this.supplyService.invoiceTotal.subscribe((res) => {
                this.invoiceTotal = res;
            })
        );
        this.subscriptions.add(
            this.supplyService.barcodeResponse.subscribe((res) => {
                this.barcodeResponse = res;
                if (res) {
                    this.addToInvoice();
                    this.supplyService.barcodeResponse.next(0);
                }
            })
        );
        this.subscriptions.add(
            this.auxiliaryService.suppliers.subscribe((res) => {
                this.suppliers = res;
            })
        );
    }

    // on destroy hook
    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // submit invoice input
    submitInvoiceInput(event: KeyboardEvent) {
        if (event.key == 'Enter') {
            if (this.barcode) {
                if (typeof this.barcode == 'string') {
                    this.submitBarcode(this.barcode);
                } else {
                    this.supplyService.barcodeResponse.next(this.barcode);
                }
                this.barcode = null;
            }
        }
    }

    // search input for text searching items
    searchItem(event: AutoCompleteCompleteEvent) {
        let filtered: any = [];
        let query = event.query;
        for (let i = 0; i < this.items.length; i++) {
            let item = this.items[i];
            if (
                item.product_name.toLowerCase().indexOf(query.toLowerCase()) >
                -1
            ) {
                // == 0 for exact search
                filtered.push(item);
            }
        }
        this.searchedItems = filtered;
    }

    // submit barcode
    submitBarcode(barcode) {
        if (barcode) {
            let index = -1;
            let allowedSymbols = ['*', '+'];
            for (let i = 0; i < allowedSymbols.length; i++) {
                if (barcode.indexOf(allowedSymbols[i]) !== -1) {
                    index = barcode.indexOf(allowedSymbols[i]);
                    break;
                }
            }
            let actualBarcode = parseInt(
                barcode.substring(index + 1, barcode.length)
            );
            if (index != -1 && index != 0) {
                this.supplyService.submitBarcode(actualBarcode);
            } else {
                this.supplyService.submitBarcode(barcode);
            }
        }
    }

    // open sell dialog
    openProductsDialog() {
        this.dialogVisible = true;
    }

    // close sell dialog
    closeProductsDialog() {
        this.dialogVisible = false;
    }

    // get selected products from dialog event
    assignSelectedProducts(products) {
        this.dialogVisible = false;
        products.forEach((element) => {
            this.supplyService.barcodeResponse.next(element);
        });
    }

    // add barcode response to invoice
    addToInvoice() {
        let item: Products = this.barcodeResponse;
        let itemToAdd = {
            product_id: item.product_id,
            sku: item.sku,
            product_name: item.product_name,
            quantity_per_unit: item.quantity_per_unit,
            quantity_in_units: 1,
            quantity: 0,
            total_qty: 0,
            weight_per_box: 0,
            total_weight: 0,
            original_price: 0,
            cost_per_weight: 0,
            cost_per_value: 0,
            total_added_costs: 0,
            calculated_price: 0,
            subtotal: 0,
            grand_total: 0,
        };
        let found = false;
        this.invoice.forEach((element, index) => {
            if (
                element.product_id_fk == itemToAdd.product_id &&
                element.product_id_fk != 0
            ) {
                this.invoice[index].quantity_in_units += 1;
                found = true;
            }
        });
        if (!found) {
            this.invoice.push(itemToAdd);
            if (this.invoiceTable) {
                setTimeout(() => {
                    this.invoiceTable.scrollTo({
                        top: this.invoiceTable.wrapperViewChild.nativeElement
                            .scrollHeight,
                    });
                }, 10);
            }
        }
        this.supplyService.invoice.next(this.invoice);
    }

    // subtract qty
    subtractQty(item) {
        let index = this.invoice.findIndex(
            (x) => x.product_id_fk == item.product_id_fk
        );
        if (this.invoice[index]['quantity_in_units'] == 1) {
            this.invoice.splice(index, 1);
        } else {
            this.invoice[index]['quantity_in_units'] -= 1;
        }
        this.supplyService.invoice.next(this.invoice);
    }

    deleteRow(row) {
        let index = this.invoice.findIndex(
            (x) => x.product_id_fk == row.product_id_fk
        );
        this.invoice.splice(index, 1);
        this.supplyService.invoice.next(this.invoice);
    }

    // trigger calculate total
    calculateTotal() {
        this.supplyService.purchaseForm.next(this.purchaseForm);
        this.supplyService.calculateTotal();
    }

    // select input on focus
    select(event) {
        event.select();
    }

    // submit checkout
    checkout() {
        if (this.purchaseForm.partner_id_fk) {
            this.purchaseForm.subtotal = this.invoiceTotal.subtotal;
            this.purchaseForm.total_weight = this.invoiceTotal.total_weight;
            this.purchaseForm.exchange_rate = this.exchangeRate.rate_value;

            let count = 0;
            if (this.purchaseForm.subtotal == 0) {
                console.log(this.purchaseForm.subtotal);

                count++;
                this.notificationService.showError(
                    `Invoice total cannot be 0.00$`,
                    'home'
                );
            }
            // validated invoice and form
            if (count == 0) {
                this.confirmationService.confirm({
                    key: 'home',
                    message: `Are you sure that you want to continue"?`,
                    header: 'Warning',
                    icon: 'pi pi-exclamation-triangle',
                    acceptButtonStyleClass: 'p-button-danger',
                    rejectButtonStyleClass: 'p-button-secondary',
                    defaultFocus: 'reject',
                    accept: () => {
                        this.supplyService.checkout(
                            this.purchaseForm,
                            this.invoice
                        );
                    },
                });
            }
        } else {
            this.supplierInvalid = true;
            this.notificationService.showError(
                'Please choose a supplier!',
                'home'
            );
        }
    }

    validate() {
        this.supplierInvalid = false;
    }

    // preventDefault(event) {
    //     // event.preventDefault()
    //     console.log(event);
    //     if (event.key == "ArrowUp" || event.key == 'ArrowDown') {
    //         event.preventDefault()
    //     }
    // }
}
