import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { ApiService } from 'src/app/_services/api.service';
import { PurchaseForm } from '../core/interfaces/supply.interface';
import * as moment from 'moment';
import { DecimalService } from '../_services/decimal.service';

@Injectable({
    providedIn: 'root',
})
export class SupplyService {
    constructor(
        private http: HttpClient,
        private notificationService: NotificationsService,
        private api: ApiService,
        private decimalService: DecimalService
    ) {}

    private host = this.api.host;

    public invoice = new BehaviorSubject([]);
    public invoiceTotal = new BehaviorSubject({});

    public barcodeResponse = new BehaviorSubject<any>(0);

    resetPurchaseForm() {
        return {
            partner_id_fk: null,
            journal_voucher_id: null,
            order_datetime: moment().format('YYYY-MM-DD'),
            subtotal: 0,
            total_weight: 0,
            costs_by_weight: 0,
            costs_by_value: 0,
            have_vat: false,
            vat_amount: 0,
            reference_number: null,
            purchase_notes: null,
        };
    }

    purchaseForm = new BehaviorSubject<PurchaseForm>(this.resetPurchaseForm());

    // submit barcode
    submitBarcode(barcode) {
        this.http.get(`${this.host}/stock/item/${barcode}`).subscribe({
            next: (item) => {
                if (item) {
                    this.barcodeResponse.next(item);
                } else {
                    this.notificationService.showError(
                        'Item not found!',
                        'home'
                    );
                }
            },
            error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'home');
            },
        });
    }

    // calculator
    calculateTotal() {
        let invoice = this.invoice.value;
        let subtotal = 0,
            total_invoice_weight = 0,
            cost_ratio = 0,
            price_per_weight = 0,
            total_invoice_qty = 0;

        // if (invoice.length === 0) return;

        invoice.forEach((element) => {
            // total quantity of element
            element.total_qty =
                element.quantity_in_units * element.quantity_per_unit +
                element.quantity;

            // invoiceTotal
            // total quantity of invoice
            total_invoice_qty = this.decimalService.add(
                total_invoice_qty,
                element.total_qty
            );

            // subtotal of element
            element.subtotal = this.decimalService.multiply(
                element.total_qty,
                element.original_price
            );

            // invoiceTotal
            // subtotal of invoice
            subtotal = this.decimalService.add(subtotal, element.subtotal);

            // total element weight
            element.total_weight = this.decimalService.multiply(
                element.weight_per_box,
                element.quantity_in_units
            );

            // invoiceTotal
            // total invoice weight
            total_invoice_weight = this.decimalService.add(
                total_invoice_weight,
                element.total_weight
            );
        });

        invoice.forEach((element) => {
            // invoiceTotal
            // invoice price per 1 KG
            price_per_weight =
                total_invoice_weight > 0
                    ? this.decimalService.divide(
                          this.purchaseForm.value.costs_by_weight,
                          total_invoice_weight
                      )
                    : 0;

            // added cost per weight for element
            element.cost_per_weight =
                (price_per_weight *
                    element.quantity_in_units *
                    element.weight_per_box) /
                element.total_qty;

            // invoiceTotal
            // calculated cost ratio by value
            cost_ratio =
                subtotal > 0
                    ? this.decimalService.divide(
                          this.purchaseForm.value.costs_by_value,
                          subtotal
                      )
                    : 0;

            // added cost per value for element
            element.cost_per_value = this.decimalService.multiply(
                element.original_price,
                cost_ratio
            );

            // element total added costs
            element.total_added_costs = this.decimalService.add(
                element.cost_per_weight,
                element.cost_per_value
            );

            // element calculated price
            element.calculated_price = this.decimalService.add(
                element.total_added_costs,
                element.original_price
            );

            // element grand total
            element.grand_total = this.decimalService.multiply(
                element.calculated_price,
                element.total_qty
            );
        });

        this.invoiceTotal.next({
            subtotal: subtotal,
            total_invoice_weight: total_invoice_weight,
            price_per_weight: price_per_weight,
            cost_ratio: cost_ratio,
            total_invoice_qty: total_invoice_qty,
        });
    }

    // submit checkout
    checkout(order, orderItems) {
        console.log(order);
        console.log(orderItems);

        this.http
            .post(`${this.host}/purchase/`, {
                purchase_order: order,
                purchase_order_items: orderItems,
            })
            .subscribe({
                next: (res: any) => {
                    this.notificationService.showSuccess(res.message, 'home');
                    this.invoice.next([]);
                    this.purchaseForm.next(this.resetPurchaseForm());

                    // this.suppliersService.getSuppliersDebts()
                    // this.suppliersService.getSupplierHistory(this.suppliersService.selectedSupplier.value)
                },
                error: (error: HttpErrorResponse) => {
                    this.notificationService.handleError(error.error, 'home');
                },
            });
    }
}
